import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"User Guide — For Server Owners","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/index.md","filePath":"openshield-xdp/user-guide/index.md","lastUpdated":1785937469000}'),i={name:"openshield-xdp/user-guide/index.md"};function n(r,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="user-guide-—-for-server-owners" tabindex="-1">User Guide — For Server Owners <a class="header-anchor" href="#user-guide-—-for-server-owners" aria-label="Permalink to &quot;User Guide — For Server Owners&quot;">​</a></h1><p>This guide is for people who run game servers, hosting nodes, or web servers and want OpenShield-XDP to &quot;just work&quot; — without needing to be a network engineer. It walks you from install to a sensible first config, explains how the protection actually works, and points you at recipes for common server types.</p><p>If you want the full technical reference instead, see <a href="/pingless-studios-docs/openshield-xdp/configuration/reference">Configuration Reference</a>.</p><h2 id="the-10-minute-setup" tabindex="-1">The 10-minute setup <a class="header-anchor" href="#the-10-minute-setup" aria-label="Permalink to &quot;The 10-minute setup&quot;">​</a></h2><h3 id="_1-install" tabindex="-1">1. Install <a class="header-anchor" href="#_1-install" aria-label="Permalink to &quot;1. Install&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OpenShield-XDP</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span></span></code></pre></div><p>The installer builds the BPF program and Go binaries, installs the systemd service, and runs the interactive profile wizard. Details: <a href="/pingless-studios-docs/openshield-xdp/getting-started/installation">Installation</a>.</p><h3 id="_2-pick-the-right-interface" tabindex="-1">2. Pick the right interface <a class="header-anchor" href="#_2-pick-the-right-interface" aria-label="Permalink to &quot;2. Pick the right interface&quot;">​</a></h3><p>OpenShield inspects traffic on <strong>one network interface</strong> — the one your public traffic arrives on. Find it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span></span></code></pre></div><p>The interface name is at the end of the line (<code>dev eth0</code>, <code>dev ens18</code>, <code>dev eno1</code>, …). That&#39;s what goes into <code>interface:</code> in your config. On most VPS providers it&#39;s <code>eth0</code> or <code>ens3</code>; on bare metal it&#39;s often <code>eno1</code> or <code>enpXsY</code>.</p><h3 id="_3-pick-a-workload-preset" tabindex="-1">3. Pick a workload preset <a class="header-anchor" href="#_3-pick-a-workload-preset" aria-label="Permalink to &quot;3. Pick a workload preset&quot;">​</a></h3><p>During install (or later with <code>sudo openshield reconfigure</code>) you choose a <strong>protection profile</strong>. This is the single most important decision — it tunes every threshold for your kind of traffic. In plain terms:</p><table tabindex="0"><thead><tr><th>Preset</th><th>Choose this if you run…</th><th>Personality</th></tr></thead><tbody><tr><td><strong>Balanced</strong></td><td>A website, API, SaaS app — the default</td><td>Protective but forgiving</td></tr><tr><td><strong>Gaming</strong></td><td>Minecraft, FiveM, Rust, CS2, voice servers</td><td>Tolerates UDP bursts and many players</td></tr><tr><td><strong>Hosting</strong></td><td>A VPS node, Docker/Pterodactyl host, shared hosting</td><td>Assumes customer spikes are legit, hunts attack patterns</td></tr><tr><td><strong>Performance</strong></td><td>Streaming, downloads, big APIs, reverse proxies</td><td>High limits, blocks only clear attacks</td></tr><tr><td><strong>CDN Edge</strong></td><td>Very high bandwidth, ISP-like traffic</td><td>Highest limits</td></tr><tr><td><strong>Strict / Ultra Strict</strong></td><td>Small sites, admin panels, low-traffic apps</td><td>Aggressive; some false positives are OK</td></tr><tr><td><strong>Database</strong></td><td>DB servers, file storage, backup targets, mail</td><td>Careful with bulk transfers</td></tr></tbody></table><p>You can change presets any time with <code>sudo openshield reconfigure</code> — it re-tunes the numbers without touching your whitelist, license, or custom edits.</p><h3 id="_4-load-and-verify" tabindex="-1">4. Load and verify <a class="header-anchor" href="#_4-load-and-verify" aria-label="Permalink to &quot;4. Load and verify&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # interactive, with a 10-second safety prompt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # confirm XDP Program: LOADED</span></span></code></pre></div><p>For production, use the systemd service so it starts on boot:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield-loader</span></span></code></pre></div><p>That&#39;s it — you&#39;re protected with sensible defaults. Everything below explains what the protection is actually doing, so you know when (and when not) to tune it.</p><h2 id="how-the-protection-works-conceptually" tabindex="-1">How the protection works, conceptually <a class="header-anchor" href="#how-the-protection-works-conceptually" aria-label="Permalink to &quot;How the protection works, conceptually&quot;">​</a></h2><p>OpenShield layers four defenses, in this order. Each one catches what the previous one can&#39;t.</p><h3 id="layer-1-—-per-ip-suspicion-scoring-peacetime" tabindex="-1">Layer 1 — Per-IP suspicion scoring (peacetime) <a class="header-anchor" href="#layer-1-—-per-ip-suspicion-scoring-peacetime" aria-label="Permalink to &quot;Layer 1 — Per-IP suspicion scoring (peacetime)&quot;">​</a></h3><p>Every source IP gets its own packet counters. When an IP exceeds a rate limit (total packets/s, bytes/s, TCP, UDP, ICMP, or SYN packets/s) it gains <strong>suspicion points</strong>. Reach 100 points and the IP is banned for an hour.</p><p>This is deliberately forgiving: one fast second doesn&#39;t ban anyone. An IP has to sustain abusive rates for several seconds before the score adds up — that&#39;s why legit bursts (loading a heavy page, a game client syncing) survive and floods don&#39;t.</p><p>Since v2.0.0 there&#39;s an important exemption: <strong>an IP that has completed a real TCP connection</strong> (it sent actual data shortly after its SYN, like a real client does) is no longer scored on the plain PPS/BPS/TCP limits. This is what stops your own SFTP uploads and backups from getting you banned. Flood protections (SYN rate, connection rate, UDP/ICMP) still apply to everyone — a spoofed flood can&#39;t fake an established connection, so nothing is lost.</p><h3 id="layer-2-—-attack-mode-the-flood-alarm" tabindex="-1">Layer 2 — Attack mode (the flood alarm) <a class="header-anchor" href="#layer-2-—-attack-mode-the-flood-alarm" aria-label="Permalink to &quot;Layer 2 — Attack mode (the flood alarm)&quot;">​</a></h3><p>Per-IP scoring alone struggles with <strong>distributed</strong> floods: a million IPs each sending a little traffic, none of them individually suspicious. So OpenShield also learns your normal traffic level (the &quot;baseline&quot;) and watches for global spikes. When total traffic jumps far above baseline and stays there for a few seconds, it declares <strong>attack mode</strong>:</p><ul><li>All per-IP thresholds tighten (default: halved)</li><li>A hard per-IP PPS cap kicks in (<code>attack_per_ip_pps</code>)</li><li>A <strong>per-port cap</strong> kicks in (<code>attack_port_pps</code>) — see Layer 3</li></ul><p>When traffic settles back down, attack mode clears and everything relaxes again. You can watch this happen live in the TUI.</p><h3 id="layer-3-—-the-per-port-cap-rotation-proof" tabindex="-1">Layer 3 — The per-port cap (rotation-proof) <a class="header-anchor" href="#layer-3-—-the-per-port-cap-rotation-proof" aria-label="Permalink to &quot;Layer 3 — The per-port cap (rotation-proof)&quot;">​</a></h3><p>Spoofed floods rotate through fake source IPs constantly, so per-IP counters stay cold. But the attacker <strong>cannot rotate the destination port</strong> — a flood aimed at your Minecraft server hits port 25565 no matter how many fake IPs it uses.</p><p><code>attack_port_pps</code> caps the <strong>total</strong> packets/s allowed toward each destination port while an attack is active (presets: 10k hosting, 15k gaming, 25k CDN). The flood&#39;s hot port betrays it, and excess packets are dropped for everyone on that port until the attack clears. Legit players on the same port get throttled, <strong>not banned</strong> — they lag for the duration of the attack instead of losing the server entirely.</p><h3 id="layer-4-—-the-behavior-engine-slow-burn-botnets" tabindex="-1">Layer 4 — The behavior engine (slow-burn botnets) <a class="header-anchor" href="#layer-4-—-the-behavior-engine-slow-burn-botnets" aria-label="Permalink to &quot;Layer 4 — The behavior engine (slow-burn botnets)&quot;">​</a></h3><p>Some attacks never spike: thousands of bots each sending a trickle, spread over hours. The behavior engine learns what your normal per-port traffic looks like (packet sizes, timing, source diversity) and groups sources into <strong>clusters</strong>. When a cluster of lookalike sources shows bot fingerprints — identical packet sizes, machine-paced timing, explosive growth — it&#39;s flagged with a confidence score.</p><p>Since v2.1.0, clusters at <strong>≥85% confidence are auto-banned for 1 hour</strong> (<code>behavior.auto_block</code>, on by default; set it to <code>false</code> for report-only mode). You can review everything in the TUI&#39;s behavior tab or with <code>sudo openshield behavior</code>.</p><div class="info custom-block"><p class="custom-block-title">The engine freezes during attacks</p><p>While an attack is declared (Layer 2), the behavior engine stops learning so it doesn&#39;t &quot;learn&quot; the attack as normal. That means it&#39;s built for <strong>slow-burn botnets and quiet recon</strong>, not for mid-flood decisions — Layers 1–3 handle the loud stuff.</p></div><h3 id="proactive-blocking-—-stop-known-bad-sources-before-they-score" tabindex="-1">Proactive blocking — stop known-bad sources before they score <a class="header-anchor" href="#proactive-blocking-—-stop-known-bad-sources-before-they-score" aria-label="Permalink to &quot;Proactive blocking — stop known-bad sources before they score&quot;">​</a></h3><p>Since v2.2.0, two features sit in front of the four layers and drop known-bad traffic outright:</p><ul><li><strong><a href="/pingless-studios-docs/openshield-xdp/user-guide/auto-fetch">Auto-fetch blocklists</a></strong> — threat-intel feeds (C2s, botnets, scanners, brute-forcers) downloaded on a schedule and loaded into the ban maps. Fetched bans expire after 2× the fetch interval, so a broken feed never blocks anyone permanently. On by default.</li><li><strong><a href="/pingless-studios-docs/openshield-xdp/user-guide/geo-blocking">Geo blocking</a></strong> — block entire countries from the TUI geo tab (key <code>0</code>); enforced as permanent subnet bans in the kernel LPM trie.</li></ul><p>Both are enforced in the same XDP pass as everything else — no per-packet userspace cost.</p><h3 id="attack-geo-analytics" tabindex="-1">Attack geo analytics <a class="header-anchor" href="#attack-geo-analytics" aria-label="Permalink to &quot;Attack geo analytics&quot;">​</a></h3><p>When GeoIP data is available, attack-end Discord reports and forensics bundles include a <strong>top-50 attacking-countries breakdown</strong> (flag emoji, IP count, peak pps/Gbps, % share — legit and established sources excluded), and the daily/weekly/monthly reports show the top attacker and top legit-user countries. Controlled by <code>reports.geo_breakdown</code> (default: on) and <code>alerter.geo_breakdown</code>.</p><h2 id="what-to-read-next" tabindex="-1">What to read next <a class="header-anchor" href="#what-to-read-next" aria-label="Permalink to &quot;What to read next&quot;">​</a></h2><ul><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/config-values">Config Values in Plain Language</a> — every important knob, what it means, and when to touch it</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/auto-fetch">Auto-Fetch Blocklists</a> — threat-intel feeds banned on a schedule (on by default)</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/geo-blocking">Geo Blocking</a> — block whole countries from the TUI</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/recipes">Recipes</a> — game server, hosting node, file/backup server, VPN</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/troubleshooting">Troubleshooting</a> — banned while uploading? attack shows but nothing dropped?</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/metrics-api">Metrics API</a> — feed your own dashboard</li><li><a href="/pingless-studios-docs/openshield-xdp/user-guide/cli">CLI Reference</a> · <a href="/pingless-studios-docs/openshield-xdp/user-guide/tui">TUI Guide</a> · <a href="/pingless-studios-docs/openshield-xdp/configuration/reference">Full Config Reference</a></li></ul>`,45)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
